frappe.ui.form.on('Employee Skill Test', {

    rating(frm, cdt, cdn) {

        let row = locals[cdt][cdn];

        if (row.rating >= 8) {
            frappe.model.set_value(
                cdt,
                cdn,
                "status",
                "Good"
            );
        } else {
            frappe.model.set_value(
                cdt,
                cdn,
                "status",
                "Needs Improvement"
            );
        }

    }

});

